export const questions: AsvabExitQuestion[] = [
  // ═══ Word Problems with Whole Numbers (asvab-ar-whole-number-problems) ═══
  // ── Easy (6) ──
  { question: 'A food pantry received 348 cans on Monday and 275 cans on Tuesday. How many cans did it receive in all?', options: ['73', '623', '513', '613'], correctAnswer: 1, explanation: '"In all" combines, so add: $348 + 275 = 623$. The answer 73 subtracts instead of adding, 513 forgets both carries, and 613 forgets the carry from the ones column into the tens.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 2 },
  { question: 'A squad of 9 shares 108 bottles of water equally. How many bottles does each member get?', options: ['117', '99', '972', '12'], correctAnswer: 3, explanation: '"Shares equally" splits, so divide: $108 \\div 9 = 12$ (check: $9 \\times 12 = 108$). The answer 117 adds the numbers, 99 subtracts them, and 972 multiplies them.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 2 },
  { question: 'A length of cable is 9 yards long. How many feet long is it?', options: ['3', '12', '27', '108'], correctAnswer: 2, explanation: 'Yards to feet is big to small, so multiply by 3: $9 \\times 3 = 27$ feet. The answer 3 divides instead of multiplying, 12 adds 9 and 3, and 108 multiplies by 12, which converts feet to inches.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 4 },
  { question: 'A recruit buys 2 water bottles at \\$4 each and a towel for \\$9. He pays with a \\$20 bill. How much change does he get?', options: ['\\$3', '\\$17', '\\$7', '\\$11'], correctAnswer: 0, explanation: 'Bottles: $2 \\times 4 = 8$. Total: $8 + 9 = 17$. Change: $20 - 17 = 3$, so \\$3. \\$17 is the total spent, one step early; \\$7 charges for only one bottle; \\$11 forgets the bottles.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 3 },
  { question: 'A club needs to drive 52 people to a game in cars that each hold 5 people. What is the fewest number of cars needed?', options: ['10', '2', '11', '47'], correctAnswer: 2, explanation: '$52 \\div 5 = 10$ remainder 2. Ten cars would leave 2 people behind, so 11 cars. The answer 10 rounds down, 2 is the remainder, and 47 subtracts one carload instead of dividing.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 5 },
  { question: 'A class starts at 8:30 a.m. and ends at 11:15 a.m. How long is the class?', options: ['3 h 15 min', '2 h 45 min', '3 h 45 min', '2 h 15 min'], correctAnswer: 1, explanation: 'Count up: 8:30 to 9:00 is 30 min, 9:00 to 11:00 is 2 h, and 11:00 to 11:15 is 15 min, so 2 h 45 min. The answer 3 h 15 min subtracts the hours ($11 - 8$) and then the smaller minutes from the larger ($30 - 15$); 3 h 45 min borrows 60 minutes for $75 - 30$ but forgets to take an hour away.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 4 },

  // ── Medium (9) ──
  { question: 'A full pack weighs 18 pounds less than three times the weight of its empty frame. The frame weighs 14 pounds. How much does the full pack weigh?', options: ['60', '42', '24', '32'], correctAnswer: 2, explanation: '"Three times the frame" is $3 \\times 14 = 42$, and "18 less than" that is $42 - 18 = 24$ pounds. The answer 60 adds the 18 instead of subtracting it, 42 stops before subtracting, and 32 adds 14 and 18 and ignores "three times."', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 2 },
  { question: 'After Leo paid \\$385 for car insurance, his checking account balance was \\$1,215. What was his balance before the payment?', options: ['\\$830', '\\$1,500', '\\$1,590', '\\$1,600'], correctAnswer: 3, explanation: '$\\text{balance} - 385 = 1{,}215$, so undo the subtraction: $1{,}215 + 385 = 1{,}600$, so \\$1,600. \\$830 subtracts the payment again, giving less than the balance after paying, which can\'t be right. \\$1,590 forgets both carries, and \\$1,500 forgets the carry into the hundreds column.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 2 },
  { question: 'Unit A logged 1,460 training hours this year and Unit B logged 985. How many more hours did Unit A log?', options: ['475', '485', '2,445', '1,525'], correctAnswer: 0, explanation: '"How many more" compares, so subtract: $1{,}460 - 985 = 475$ (check: $985 + 475 = 1{,}460$). The answer 2,445 adds the two totals because of the word "more"; 485 forgets to reduce the tens digit after borrowing; 1,525 subtracts the smaller digit from the larger in every column.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 2 },
  { question: 'A cook earns \\$15 an hour for the first 40 hours of a week and \\$22 an hour for each hour beyond 40. She worked 45 hours this week. What was her pay?', options: ['\\$675', '\\$990', '\\$110', '\\$710'], correctAnswer: 3, explanation: 'Regular: $40 \\times 15 = 600$. Overtime: $5 \\times 22 = 110$. Total: $600 + 110 = 710$, so \\$710. \\$675 pays all 45 hours at \\$15, \\$990 pays all 45 at \\$22, and \\$110 is only the overtime part.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 3 },
  { question: 'A unit orders 6 boxes of work gloves at \\$14 a box and 5 rolls of tape at \\$3 a roll. It pays with \\$150. How much change does it get?', options: ['\\$99', '\\$51', '\\$133', '\\$66'], correctAnswer: 1, explanation: 'Gloves: $6 \\times 14 = 84$. Tape: $5 \\times 3 = 15$. Total: $84 + 15 = 99$. Change: $150 - 99 = 51$, so \\$51. \\$99 is the total, one step early; \\$133 subtracts one box and one roll ($150 - 14 - 3$); \\$66 forgets the tape.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 3 },
  { question: 'A store sells shirts for \\$11 each and hats for \\$9 each. Which expression gives the total cost, in dollars, of 4 shirts and 2 hats?', options: ['$(4 + 2) \\times (11 + 9)$', '$4 \\times (11 + 2) \\times 9$', '$4 \\times 11 + 2 \\times 9$', '$4 + 11 \\times 2 + 9$'], correctAnswer: 2, explanation: 'Shirts cost $4 \\times 11$ and hats cost $2 \\times 9$; add them: $4 \\times 11 + 2 \\times 9 = 44 + 18 = 62$. The expression $(4 + 2) \\times (11 + 9)$ charges every item the price of a shirt and a hat together (\\$120), and $4 + 11 \\times 2 + 9$ pairs the wrong numbers.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 3 },
  { question: 'A storage room is 21 ft long and 12 ft wide. Floor tile costs \\$2 per square foot. What will it cost to tile the floor?', options: ['\\$504', '\\$56', '\\$132', '\\$252'], correctAnswer: 0, explanation: 'Area: $21 \\times 12 = 252$ sq ft. Cost: $252 \\times 2 = 504$, so \\$504. The price is already per square foot, so no conversion is needed: \\$56 converts to square yards anyway ($252 \\div 9 = 28$). \\$132 prices the perimeter (66 ft), and \\$252 stops at the area and never multiplies by the price.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 4 },
  { question: 'A night shift starts at 11:20 p.m. and ends at 7:05 a.m. the next morning. How long is the shift?', options: ['4 h 15 min', '8 h 45 min', '7 h 45 min', '7 h 25 min'], correctAnswer: 2, explanation: 'Count up: 11:20 p.m. to midnight is 40 min, midnight to 7:00 a.m. is 7 h, and 7:00 to 7:05 is 5 min, so 7 h 45 min. The answer 4 h 15 min subtracts the clock times as if they were in the same half of the day, and 7 h 25 min adds the 20 and 5 minutes on the clock instead of counting 40 minutes to midnight.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 4 },
  { question: 'A printing job needs 1,250 sheets of paper. Paper comes in packs of 200 sheets. How many packs must be bought?', options: ['6', '7', '50', '1,050'], correctAnswer: 1, explanation: '$1{,}250 \\div 200 = 6$ remainder 50, because $6 \\times 200 = 1{,}200$. Six packs are 50 sheets short, so buy 7. The answer 6 rounds down, 50 is the remainder, and 1,050 subtracts one pack instead of dividing.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 5 },

  // ── Hard (5) ──
  { question: 'An L-shaped patio is a 24 ft by 10 ft rectangle with a 12 ft by 6 ft rectangle attached along its 24-foot side. Pavers cost \\$5 per square foot. What will the pavers cost?', options: ['\\$520', '\\$1,200', '\\$1,920', '\\$1,560'], correctAnswer: 3, explanation: 'Areas: $24 \\times 10 = 240$ and $12 \\times 6 = 72$, so $240 + 72 = 312$ sq ft. Cost: $312 \\times 5 = 1{,}560$, so \\$1,560. \\$1,200 prices only the large rectangle, \\$1,920 prices the full 24 ft by 16 ft rectangle around the L, and \\$520 adds the two perimeters (104 ft) instead of the areas.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 4 },
  { question: 'A school orders 640 folders. Folders come in boxes of 48, and each box costs \\$9. What is the least the school can spend and still get all 640 folders?', options: ['\\$117', '\\$126', '\\$144', '\\$5,760'], correctAnswer: 1, explanation: '$640 \\div 48 = 13$ remainder 16, because $48 \\times 13 = 624$. Thirteen boxes are 16 folders short, so buy 14: $14 \\times 9 = 126$, so \\$126. \\$117 buys only 13 boxes, \\$144 uses the remainder 16 as the number of boxes, and \\$5,760 prices every folder at \\$9.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 5 },
  { question: 'A repair bill came to \\$410. It included \\$110 for parts plus labor at \\$75 an hour. How many hours of labor were billed?', options: ['4', '300', '5', '7'], correctAnswer: 0, explanation: 'Labor cost: $410 - 110 = 300$. Hours: $300 \\div 75 = 4$ (check: $4 \\times 75 + 110 = 410$). The answer 300 is the labor cost in dollars, not hours; 5 divides the whole \\$410 by \\$75 and rounds, forgetting the parts; 7 adds the parts instead of subtracting them.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 3 },
  { question: 'A gym floor 30 ft by 18 ft will be refinished at \\$6 per square yard. What will the refinishing cost?', options: ['\\$360', '\\$3,240', '\\$1,080', '\\$576'], correctAnswer: 0, explanation: 'Convert the sides first: 30 ft = 10 yd and 18 ft = 6 yd, so the area is $10 \\times 6 = 60$ sq yd (or $540 \\div 9 = 60$). Cost: $60 \\times 6 = 360$, so \\$360. \\$3,240 prices 540 square feet at the square-yard rate, \\$1,080 divides by 3 instead of 9, and \\$576 prices the perimeter (96 ft).', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 6 },
  { question: 'A technician\'s three repair jobs took 1 h 50 min, 2 h 25 min and 1 h 45 min. What was the total time for the three jobs, in minutes?', options: ['240 minutes', '120 minutes', '520 minutes', '360 minutes'], correctAnswer: 3, explanation: 'Hours: $1 + 2 + 1 = 4$ h, which is 240 min. Minutes: $50 + 25 + 45 = 120$ min. Total: $240 + 120 = 360$ minutes. The answer 240 counts only the hours, 120 counts only the minutes, and 520 treats 4 hours as 400 minutes, as if an hour had 100 minutes.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-whole-number-problems', part: 6 },
  // ═══ Fractions and Decimals in Context (asvab-ar-fractions-decimals) ═══
  // ---- Part 2: fraction of a quantity ----
  { question: 'A hospital ward has 96 beds, and $\\frac{3}{4}$ of them are occupied. How many beds are occupied?', options: ['24', '72', '32', '128'], correctAnswer: 1, explanation: '$96 \\div 4 = 24$, and $24 \\times 3 = 72$ beds. The 24 beds are the empty ones (one fourth), 32 divides by 3 instead of 4, and 128 flips the fraction, giving more beds than the ward has.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 2 },
  { question: 'Of the 120 people who took a fitness test, $\\frac{7}{10}$ passed. How many people did not pass?', options: ['84', '12', '113', '36'], correctAnswer: 3, explanation: 'The fraction who did not pass is $1 - \\frac{7}{10} = \\frac{3}{10}$, and $120 \\div 10 \\times 3 = 36$ people. 84 is the number who passed (the fraction used, not the fraction left), 12 is one tenth only, and 113 subtracts the numerator 7 from 120.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 2 },
  { question: 'A recruiter has met $\\frac{3}{8}$ of her monthly goal by signing 15 applicants. What is her monthly goal, in applicants?', options: ['40', '25', '45', '120'], correctAnswer: 0, explanation: 'Three eighths is 15 applicants, so one eighth is $15 \\div 3 = 5$ and the goal is $5 \\times 8 = 40$. 25 is the number she still needs, 45 multiplies 15 by 3 instead of dividing, and 120 multiplies by 8 without first dividing by 3.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 2 },
  { question: 'A food bank starts the week with 840 cans. It gives out $\\frac{1}{4}$ of the cans on Monday, $\\frac{2}{3}$ of the remaining cans on Tuesday, and $\\frac{1}{2}$ of what is left on Wednesday. How many cans remain after Wednesday?', options: ['210', '105', '70', '420'], correctAnswer: 1, explanation: 'Monday: 210 given out, 630 left. Tuesday: $\\frac{2}{3}$ of 630 is 420, so 210 left. Wednesday: half of 210 is given out, leaving 105. (Shortcut: $\\frac{3}{4} \\times \\frac{1}{3} \\times \\frac{1}{2} = \\frac{1}{8}$ of 840.) 210 forgets Wednesday, 420 is Tuesday\'s handout, and 70 multiplies the fractions given out ($\\frac{1}{4} \\times \\frac{2}{3} \\times \\frac{1}{2} = \\frac{1}{12}$) instead of the fractions left.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 2 },
  { question: 'Ana spent $\\frac{1}{3}$ of her savings on a laptop and then $\\frac{1}{4}$ of what was left on a phone. She has \\$360 left. How much did she have in savings at the start?', options: ['\\$540', '\\$864', '\\$720', '\\$480'], correctAnswer: 2, explanation: 'After the laptop $\\frac{2}{3}$ is left, and after the phone $\\frac{3}{4}$ of that is left: $\\frac{2}{3} \\times \\frac{3}{4} = \\frac{1}{2}$. Half her savings is \\$360, so she started with \\$720. \\$864 applies the $\\frac{1}{4}$ to the original savings ($\\frac{5}{12}$ left), \\$540 undoes only the laptop step, and \\$480 undoes only the phone step.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 2 },

  // ---- Part 3: adding and subtracting fractions and mixed numbers ----
  { question: 'A plumber joins two pieces of pipe, one $1\\frac{1}{2}$ feet long and one $2\\frac{1}{4}$ feet long. How many feet long is the joined pipe?', options: ['$3\\frac{1}{3}$', '$\\frac{3}{4}$', '$3\\frac{3}{8}$', '$3\\frac{3}{4}$'], correctAnswer: 3, explanation: 'With fourths: $1\\frac{2}{4} + 2\\frac{1}{4} = 3\\frac{3}{4}$ feet. $3\\frac{1}{3}$ adds tops and bottoms of the fractions ($\\frac{2}{6}$), $\\frac{3}{4}$ subtracts the lengths, and $3\\frac{3}{8}$ multiplies them.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 3 },
  { question: 'A 12-foot length of gutter has two pieces cut from it: one $4\\frac{5}{8}$ feet long and one $3\\frac{3}{4}$ feet long. How many feet of gutter are left?', options: ['$4\\frac{3}{8}$', '$3\\frac{5}{8}$', '$8\\frac{3}{8}$', '$4\\frac{5}{8}$'], correctAnswer: 1, explanation: 'The cuts total $4\\frac{5}{8} + 3\\frac{6}{8} = 7\\frac{11}{8} = 8\\frac{3}{8}$ feet, and $12 - 8\\frac{3}{8} = 11\\frac{8}{8} - 8\\frac{3}{8} = 3\\frac{5}{8}$ feet. $8\\frac{3}{8}$ is the length cut off (stopped early), $4\\frac{5}{8}$ drops the 1 carried from $\\frac{11}{8}$, and $4\\frac{3}{8}$ subtracts without borrowing.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 3 },
  { question: 'Four work teams have finished these fractions of their projects: $\\frac{2}{3}$, $\\frac{5}{8}$, $\\frac{7}{10}$ and $\\frac{3}{5}$. Which fraction shows the team that is furthest along?', options: ['$\\frac{7}{10}$', '$\\frac{2}{3}$', '$\\frac{5}{8}$', '$\\frac{3}{5}$'], correctAnswer: 0, explanation: 'As decimals: $\\frac{7}{10} = 0.7$, $\\frac{2}{3} \\approx 0.667$, $\\frac{5}{8} = 0.625$ and $\\frac{3}{5} = 0.6$, so $\\frac{7}{10}$ is greatest (cross-multiplying with $\\frac{2}{3}$: 21 vs 20). $\\frac{2}{3}$ is close but just short, and $\\frac{5}{8}$ has a bigger denominator than $\\frac{2}{3}$, which does not make it bigger.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 3 },
  { question: 'A volunteer must log 20 service hours this month. So far she has logged $4\\frac{3}{4}$ hours, $5\\frac{2}{3}$ hours and $6\\frac{1}{2}$ hours. How many more hours must she log?', options: ['$4\\frac{1}{12}$', '$16\\frac{11}{12}$', '$3\\frac{1}{12}$', '$4\\frac{11}{12}$'], correctAnswer: 2, explanation: 'In twelfths: $4\\frac{9}{12} + 5\\frac{8}{12} + 6\\frac{6}{12} = 15\\frac{23}{12} = 16\\frac{11}{12}$ hours. Then $20 = 19\\frac{12}{12}$, and $19\\frac{12}{12} - 16\\frac{11}{12} = 3\\frac{1}{12}$ hours. $16\\frac{11}{12}$ is the time already logged, $4\\frac{1}{12}$ drops the 1 carried from $\\frac{23}{12}$, and $4\\frac{11}{12}$ subtracts the wholes and keeps the $\\frac{11}{12}$ without borrowing.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 3 },

  // ---- Part 4: multiplying and dividing fractions ----
  { question: 'How many $\\frac{1}{4}$-pound burgers can be made from 6 pounds of ground beef?', options: ['24', '1.5', '10', '4'], correctAnswer: 0, explanation: '$6 \\div \\frac{1}{4} = 6 \\times 4 = 24$ burgers. 1.5 multiplies by $\\frac{1}{4}$ instead of dividing (each burger is less than a pound, so there must be more than 6), 10 adds 6 and 4, and 4 is the number of burgers in just one pound.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 4 },
  { question: 'A $2\\frac{1}{4}$-pound block of cheese is cut into portions of $\\frac{3}{8}$ pound each. How many portions are there?', options: ['$\\frac{27}{32}$', '$5\\frac{1}{3}$', '$6$', '$18$'], correctAnswer: 2, explanation: '$\\frac{9}{4} \\div \\frac{3}{8} = \\frac{9}{4} \\times \\frac{8}{3} = 6$ portions. $\\frac{27}{32}$ multiplies instead of dividing, $5\\frac{1}{3}$ divides only the 2 pounds and drops the $\\frac{1}{4}$, and 18 multiplies by 8 but forgets to divide by 3.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 4 },
  { question: 'At a company, $\\frac{2}{3}$ of the employees work on-site, and $\\frac{3}{8}$ of the on-site employees work the night shift. What fraction of all the employees work on-site at night?', options: ['$\\frac{5}{11}$', '$\\frac{1}{4}$', '$\\frac{16}{9}$', '$\\frac{5}{12}$'], correctAnswer: 1, explanation: '"$\\frac{3}{8}$ of $\\frac{2}{3}$" means multiply: cancel the 3s and $\\frac{2}{8} = \\frac{1}{4}$. $\\frac{5}{11}$ adds tops and bottoms, $\\frac{16}{9}$ divides (and is more than all the employees), and $\\frac{5}{12}$ uses the on-site employees who do not work nights.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 4 },
  { question: 'A 40-gallon drum is $\\frac{3}{4}$ full of water. The water is poured into containers that hold $2\\frac{1}{2}$ gallons each. How many containers can be filled?', options: ['16', '75', '4', '12'], correctAnswer: 3, explanation: 'The drum holds $\\frac{3}{4} \\times 40 = 30$ gallons, and $30 \\div \\frac{5}{2} = 30 \\times \\frac{2}{5} = 12$ containers. 16 divides the full 40 gallons and ignores the $\\frac{3}{4}$, 75 multiplies 30 by $2\\frac{1}{2}$ instead of dividing, and 4 uses the 10 empty gallons.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 4 },

  // ---- Part 5: decimals and money ----
  { question: 'Movie tickets cost \\$11.75 each. How much do 4 tickets cost?', options: ['\\$44.75', '\\$47.00', '\\$15.75', '\\$470.00'], correctAnswer: 1, explanation: '$4 \\times 11 = 44$ and $4 \\times 0.75 = 3$, so the total is \\$47.00. \\$44.75 multiplies only the dollars and keeps 75 cents once, \\$15.75 adds 4 instead of multiplying, and \\$470.00 puts the decimal point one place too far right.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 5 },
  { question: 'A customer pays for a \\$31.85 order with a \\$50 bill. How much change should the customer get?', options: ['\\$19.15', '\\$81.85', '\\$19.85', '\\$18.15'], correctAnswer: 3, explanation: '$50.00 - 31.85 = 18.15$, so \\$18.15. Count up: 15 cents to \\$32, then \\$18 to \\$50. \\$19.15 forgets to borrow from the dollars, \\$19.85 subtracts the dollars and copies the cents, and \\$81.85 adds.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 5 },
  { question: 'A mechanic charges \\$64.50 an hour for labor. A repair takes 2.5 hours of labor and \\$38.20 in parts. What is the total bill?', options: ['\\$199.45', '\\$161.25', '\\$167.20', '\\$105.20'], correctAnswer: 0, explanation: 'Labor: $64.50 \\times 2 = 129$ plus half of 64.50 ($32.25$) is \\$161.25. Add parts: $161.25 + 38.20 = 199.45$, so \\$199.45. \\$161.25 leaves out the parts, \\$167.20 charges only 2 hours of labor, and \\$105.20 adds 2.5 to the rate instead of multiplying.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 5 },
  { question: 'A pack of 8 batteries costs \\$9.60, and a single battery costs \\$1.45. How much is saved per battery by buying the pack?', options: ['\\$1.20', '\\$0.25', '\\$2.00', '\\$8.15'], correctAnswer: 1, explanation: 'Pack price per battery: $9.60 \\div 8 = 1.20$. Savings per battery: $1.45 - 1.20 = 0.25$, so \\$0.25. \\$1.20 is the pack price per battery (stopped early), \\$2.00 is the savings on all 8 batteries rather than on each one, and \\$8.15 subtracts the single price from the pack price.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 5 },
  { question: 'A household uses 640 kilowatt-hours of electricity in a month at \\$0.135 per kilowatt-hour, plus a \\$12.50 monthly service fee. What is the electric bill?', options: ['\\$86.40', '\\$876.50', '\\$98.90', '\\$21.14'], correctAnswer: 2, explanation: '$640 \\times 135 = 86{,}400$, and three decimal places give 86.40, so the energy costs \\$86.40; adding the \\$12.50 fee gives \\$98.90. \\$86.40 forgets the fee, \\$876.50 puts the decimal point one place too far right, and \\$21.14 puts it one place too far left before adding the fee.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 5 },

  // ---- Part 6: traps ----
  { question: 'A hiker covers $\\frac{3}{8}$ of a 40-mile trail on the first day and $\\frac{1}{5}$ of the remaining distance on the second day. How many miles of trail are left after the second day?', options: ['17', '25', '20', '5'], correctAnswer: 2, explanation: 'Day 1: $40 \\div 8 \\times 3 = 15$ miles, leaving 25. Day 2: $\\frac{1}{5}$ of 25 is 5 miles, leaving 20. 17 takes $\\frac{1}{5}$ of the full 40 miles on day 2 (the "of the rest" trap), 25 stops after day 1, and 5 is the day 2 distance, not the distance left.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 6 },
  { question: 'Fencing costs \\$7.80 per foot. How much does 45 feet of fencing cost?', options: ['\\$35.10', '\\$360.00', '\\$3,510.00', '\\$351.00'], correctAnswer: 3, explanation: '$7.80 \\times 45$: $7 \\times 45 = 315$ and $0.80 \\times 45 = 36$, so the cost is \\$351.00. Estimate: about \\$8 $\\times$ 45 $= 360$, which rules out \\$35.10 and \\$3,510.00 (decimal point off by a factor of 10); \\$360.00 is the rounded estimate itself, not the exact cost.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-fractions-decimals', part: 6 },
  // ═══ Percents, Discounts and Interest (asvab-ar-percents-interest) ═══
  // ── Easy (6) ──
  { question: 'A high school has 600 students, and 5% of them ride a bike to school. How many students ride a bike to school?', options: ['60', '570', '30', '120'], correctAnswer: 2, explanation: '10% of 600 is 60, and 5% is half of that: $60 \\div 2 = 30$ students. The answer 60 is 10%, not 5%. 570 is the 95% who do not bike, and 120 treats 5% as one fifth, which is really 20%.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 2 },
  { question: 'A company received 80 job applications and hired 20 of the applicants. What percent of the applicants were hired?', options: ['20%', '25%', '75%', '4%'], correctAnswer: 1, explanation: 'Part ÷ whole: $\\frac{20}{80} = \\frac{1}{4} = 25\\%$. 20% puts a percent sign on the number hired, 75% is the share NOT hired, and 4% comes from dividing 80 by 20 (the whole by the part).', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 2 },
  { question: 'A pair of running shoes regularly costs \\$68. They are on sale for 25% off. What is the sale price?', options: ['\\$17', '\\$43', '\\$85', '\\$51'], correctAnswer: 3, explanation: '25% is one quarter: $68 \\div 4 = 17$ off, so the sale price is $68 - 17 = 51$, or \\$51. \\$17 is the discount, not the price you pay. \\$43 subtracts 25 dollars instead of 25%, and \\$85 adds the discount, which can\'t be right for a sale price.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 3 },
  { question: 'A unit orders \\$150 worth of cleaning supplies, and the sales tax is 6%. How much is the sales tax?', options: ['\\$90', '\\$9', '\\$159', '\\$141'], correctAnswer: 1, explanation: '1% of 150 is 1.50, so 6% is $6 \\times 1.50 = 9$, or \\$9. \\$90 uses 6% as 0.6. \\$159 is the total with tax, but the question asks for the tax alone, and \\$141 subtracts the tax from the price.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 4 },
  { question: 'Rosa keeps \\$900 in a savings account that pays 3% simple interest per year. How much interest does she earn in one year?', options: ['\\$27', '\\$270', '\\$927', '\\$2,700'], correctAnswer: 0, explanation: '1% of 900 is 9, so 3% is $3 \\times 9 = 27$, or \\$27. \\$270 uses 3% as 0.3, and \\$2,700 uses the rate as 3 instead of 0.03. \\$927 is the balance after a year, not the interest earned.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 5 },
  { question: 'A salesperson earns a 10% commission. Last month he sold \\$4,300 worth of equipment. What was his commission?', options: ['\\$43', '\\$3,870', '\\$4,730', '\\$430'], correctAnswer: 3, explanation: '10% means move the decimal point one place left: 4,300 becomes 430, so \\$430. \\$43 moves the point two places (that is 1%). \\$4,730 adds the commission to the sales, and \\$3,870 subtracts it.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 4 },

  // ── Medium (9) ──
  { question: 'A company has 120 soldiers, and 18 of them are left-handed. What percent of the company is left-handed?', options: ['85%', '15%', '18%', '1.5%'], correctAnswer: 1, explanation: 'Part ÷ whole: $\\frac{18}{120} = \\frac{3}{20} = 15\\%$ (check: 10% of 120 is 12 and 5% is 6, and $12 + 6 = 18$). 85% is the share who are right-handed. 18% labels the count as a percent, and 1.5% slips the decimal when turning 0.15 into a percent.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 2 },
  { question: 'Jamal has saved \\$42, which is 35% of the price of a used laptop. What is the price of the laptop?', options: ['\\$14.70', '\\$77.00', '\\$120.00', '\\$56.70'], correctAnswer: 2, explanation: 'Find the whole: $42 = 0.35 \\times \\text{price}$, so the price is $42 \\div 0.35 = 4{,}200 \\div 35 = 120$, or \\$120.00. Check: 25% of 120 is 30 and 10% is 12, and $30 + 12 = 42$. \\$14.70 is 35% of \\$42, which takes the percent of the part. \\$56.70 adds that 35% of \\$42 onto the \\$42, and \\$77.00 adds 42 and 35.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 2 },
  { question: 'A store buys rain jackets for \\$60 each and marks them up 45%. What is the store\'s selling price for one jacket?', options: ['\\$27', '\\$105', '\\$33', '\\$87'], correctAnswer: 3, explanation: 'Markup: 25% of 60 is 15 and 20% is 12, so 45% is 27. Selling price: $60 + 27 = 87$, or \\$87. \\$27 is the markup alone. \\$105 adds 45 dollars instead of 45%, and \\$33 subtracts the markup as if it were a discount.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 3 },
  { question: 'The monthly rent on an apartment went up from \\$900 to \\$972. By what percent did the rent increase?', options: ['8%', '72%', '108%', '0.08%'], correctAnswer: 0, explanation: 'Change ÷ original: $972 - 900 = 72$, and $\\frac{72}{900} = \\frac{8}{100} = 8\\%$. 72% is the dollar change labeled as a percent. 108% is the new rent as a percent of the old rent, not the increase, and 0.08% writes the decimal 0.08 with a percent sign without multiplying by 100.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 3 },
  { question: 'A \\$120 fleece jacket is 25% off, and a coupon takes an extra 10% off the sale price. What is the final price?', options: ['\\$78', '\\$90', '\\$81', '\\$39'], correctAnswer: 2, explanation: 'One discount at a time: 25% off 120 leaves 90, and 10% of 90 is 9, so $90 - 9 = 81$, or \\$81. \\$78 adds the discounts into one 35% off, the classic trap. \\$90 forgets the coupon, and \\$39 is the total amount saved.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 3 },
  { question: 'Shoes priced at \\$70 are 20% off, and a 5% sales tax is charged on the sale price. What is the total cost?', options: ['\\$56.00', '\\$59.50', '\\$53.20', '\\$58.80'], correctAnswer: 3, explanation: 'Sale price: 20% of 70 is 14, so $70 - 14 = 56$. Tax: 5% of 56 is 2.80. Total: $56 + 2.80 = 58.80$, so \\$58.80. \\$56.00 forgets the tax. \\$59.50 taxes the original \\$70 (giving \\$73.50) and then subtracts the \\$14 discount, and \\$53.20 subtracts the tax.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 4 },
  { question: 'A sales rep earns \\$450 a week plus 6% of her sales. This week she sold \\$3,000 worth of products. What is her pay for the week?', options: ['\\$630', '\\$180', '\\$2,250', '\\$456'], correctAnswer: 0, explanation: 'Commission: 1% of 3,000 is 30, so 6% is 180. Pay: $450 + 180 = 630$, so \\$630. \\$180 is the commission without the base pay. \\$2,250 uses 6% as 0.6, and \\$456 just adds 6 dollars to the base pay.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 4 },
  { question: 'Carla borrows \\$5,000 at 7% simple interest for 2 years. How much must she repay in all, principal plus interest?', options: ['\\$700', '\\$5,700', '\\$5,350', '\\$75,000'], correctAnswer: 1, explanation: 'One year: 7% of 5,000 is $7 \\times 50 = 350$. Two years: 700. Total: $5{,}000 + 700 = 5{,}700$, so \\$5,700. \\$700 is the interest alone. \\$5,350 charges only one year, and \\$75,000 uses the rate as 7 instead of 0.07.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 5 },
  { question: 'A credit union pays 5% simple interest per year. How much interest does a \\$4,200 deposit earn in 18 months?', options: ['\\$210', '\\$4,515', '\\$315', '\\$3,780'], correctAnswer: 2, explanation: 'One year: 10% of 4,200 is 420, so 5% is 210. Eighteen months is 1.5 years: $210 + 105 = 315$, so \\$315. \\$210 is only one year. \\$3,780 treats 18 months as 18 years, and \\$4,515 is the balance, not the interest.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 5 },

  // ── Hard (5) ──
  { question: 'A fleet car bought for \\$15,000 loses 20% of its value each year. What is the car worth after 2 years?', options: ['\\$9,000', '\\$12,000', '\\$5,400', '\\$9,600'], correctAnswer: 3, explanation: 'Year 1: 20% of 15,000 is 3,000, leaving 12,000. Year 2: 20% of 12,000 is 2,400, leaving $12{,}000 - 2{,}400 = 9{,}600$, so \\$9,600. \\$9,000 adds the two years into one 40% loss on the original price. \\$12,000 stops after one year, and \\$5,400 is the total value lost.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 3 },
  { question: 'After a 15% discount, a socket set sells for \\$68. What was the price before the discount?', options: ['\\$80.00', '\\$78.20', '\\$83.00', '\\$57.80'], correctAnswer: 0, explanation: 'The sale price is 85% of the original: $68 \\div 0.85 = 6{,}800 \\div 85 = 80$, so \\$80.00. Check: 15% of 80 is 12, and $80 - 12 = 68$. \\$78.20 adds 15% of \\$68 back on, but the discount was 15% of the original price. \\$83.00 adds \\$15, and \\$57.80 takes another 15% off, which goes the wrong way.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 3 },
  { question: 'A salesman earns \\$500 a week plus a 4% commission on his sales. Last week his total pay was \\$740. How much did he sell last week?', options: ['\\$240', '\\$18,500', '\\$6,000', '\\$600'], correctAnswer: 2, explanation: 'Commission: $740 - 500 = 240$. Sales: $240 \\div 0.04 = 24{,}000 \\div 4 = 6{,}000$, so \\$6,000. \\$240 is the commission, not the sales. \\$18,500 divides the whole \\$740 by 0.04, forgetting to remove the base pay, and \\$600 divides by 0.4 instead of 0.04.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 4 },
  { question: 'Mia borrows \\$3,000 at 6% simple interest for 2 years and repays the loan plus interest in 24 equal monthly payments. How much is each payment?', options: ['\\$125.00', '\\$140.00', '\\$132.50', '\\$15.00'], correctAnswer: 1, explanation: 'Interest: 6% of 3,000 is 180 per year, so 360 for 2 years. Total: $3{,}000 + 360 = 3{,}360$. Each payment: $3{,}360 \\div 24 = 140$, so \\$140.00. \\$125.00 repays only the principal. \\$132.50 includes just one year of interest, and \\$15.00 spreads only the interest over 24 months.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 5 },
  { question: 'A camera cost \\$250. The store raised the price by 20%, and later lowered the new price by 20%. What is the camera\'s price now?', options: ['\\$240', '\\$250', '\\$200', '\\$300'], correctAnswer: 0, explanation: 'Raise: 20% of 250 is 50, so the price became 300. Lower: 20% of 300 is 60, so $300 - 60 = 240$, or \\$240. \\$250 assumes the two changes cancel, but the 20% cut is taken of the bigger price. \\$200 takes 20% off the original, and \\$300 stops after the raise.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-percents-interest', part: 6 },
  // ═══ Ratios, Proportions and Rates (asvab-ar-ratios-rates) ═══
  // ── Easy (6) ──
  { question: 'A garden has 12 tomato plants and 20 pepper plants. What is the ratio of tomato plants to pepper plants in simplest form?', options: ['5:3', '3:8', '3:5', '5:8'], correctAnswer: 2, explanation: 'Tomato to pepper puts tomato first: $12 : 20$, and dividing both by 4 gives $3 : 5$. The ratio $5 : 3$ flips the order, and $3 : 8$ and $5 : 8$ compare one kind of plant to all 32 plants.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 2 },
  { question: 'A utility crew lays 6 miles of cable in 2 days. At the same rate, how many miles of cable does it lay in 7 days?', options: ['42', '14', '13', '21'], correctAnswer: 3, explanation: 'Rate: $6 \\div 2 = 3$ miles per day, so 7 days gives $7 \\times 3 = 21$ miles. The answer 42 multiplies 6 by 7 as if 6 miles were laid each day, 14 multiplies the 2 days by 7, and 13 adds 6 and 7.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 3 },
  { question: 'A truck drives 260 miles at a steady 52 miles per hour. How many hours does the drive take?', options: ['5', '312', '208', '13,520'], correctAnswer: 0, explanation: 'Time = distance ÷ rate: $260 \\div 52 = 5$ hours (check: $52 \\times 5 = 260$). The answer 312 adds the numbers, 208 subtracts them, and 13,520 multiplies them.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 4 },
  { question: 'A car gets 32 miles per gallon. How many gallons of gas does it use on a 224-mile drive?', options: ['192', '7,168', '7', '256'], correctAnswer: 2, explanation: 'Gallons = miles ÷ miles per gallon: $224 \\div 32 = 7$ gallons (check: $32 \\times 7 = 224$). The answer 7,168 multiplies instead of dividing, 192 subtracts 32 from 224, and 256 adds them.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 5 },
  { question: 'A 24-pack of bottled water costs \\$6.00. What is the price per bottle?', options: ['\\$4.00', '\\$0.25', '\\$144.00', '\\$18.00'], correctAnswer: 1, explanation: 'Price per bottle = price ÷ bottles: $6.00 \\div 24 = 0.25$, so \\$0.25. \\$4.00 divides the wrong way ($24 \\div 6$), \\$144.00 multiplies, and \\$18.00 subtracts 6 from 24.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 5 },
  { question: 'A 60-acre farm is planted with corn and wheat in the ratio 7 to 3. How many acres are planted with corn?', options: ['18', '140', '6', '42'], correctAnswer: 3, explanation: 'Shares: $7 + 3 = 10$. One share: $60 \\div 10 = 6$ acres. Corn: $7 \\times 6 = 42$ acres. The answer 18 is the wheat, 6 is a single share, and 140 multiplies 60 by $\\frac{7}{3}$, more acres than the whole farm.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 2 },

  // ── Medium (9) ──
  { question: 'A school fundraiser sold 50 tickets. Adult, student and child tickets were sold in the ratio 5 : 3 : 2. How many child tickets were sold?', options: ['10', '25', '15', '5'], correctAnswer: 0, explanation: 'Shares: $5 + 3 + 2 = 10$. One share: $50 \\div 10 = 5$ tickets. Child tickets: $2 \\times 5 = 10$. The answer 25 is the adult tickets, 15 is the student tickets, and 5 is a single share.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 2 },
  { question: 'A bin holds 30 red tags and 18 blue tags. How many blue tags must be added so that the ratio of red tags to blue tags is 5 to 4?', options: ['24', '12', '42', '6'], correctAnswer: 3, explanation: 'Red stays at 30, which is $6 \\times 5$, so blue must become $6 \\times 4 = 24$. Tags to add: $24 - 18 = 6$. The answer 24 is the new number of blue tags, not the number added; 42 adds 24 more on top of the 18; and 12 makes the two colors equal, a ratio of 1 to 1.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 2 },
  { question: 'In a unit, the ratio of soldiers who passed a fitness test to those who did not pass is 9 to 1. If 180 soldiers took the test, how many passed?', options: ['18', '20', '162', '1,620'], correctAnswer: 2, explanation: 'Shares: $9 + 1 = 10$. One share: $180 \\div 10 = 18$. Passed: $9 \\times 18 = 162$. The answer 18 is the number who did not pass, 20 divides 180 by 9 instead of by the 10 total shares, and 1,620 multiplies 180 by 9.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 6 },
  { question: 'A two-stroke engine needs gas and oil mixed in the ratio 40 to 1. How many ounces of oil are needed for 2.5 gallons of gas? (1 gallon = 128 ounces)', options: ['8', '3.2', '100', '320'], correctAnswer: 0, explanation: 'Gas: $2.5 \\times 128 = 256 + 64 = 320$ ounces. Oil: $320 \\div 40 = 8$ ounces. The answer 320 is the gas in ounces (one step early), 3.2 is the oil for just 1 gallon ($128 \\div 40$), and 100 multiplies 2.5 by 40 instead of dividing.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 3 },
  { question: 'On a map, $\\frac{1}{2}$ inch represents 15 miles. Two towns are $4\\frac{1}{2}$ inches apart on the map. How many miles apart are they?', options: ['67.5', '135', '120', '9'], correctAnswer: 1, explanation: 'If $\\frac{1}{2}$ inch is 15 miles, then 1 inch is 30 miles, and $4\\frac{1}{2} \\times 30 = 120 + 15 = 135$ miles. The answer 67.5 treats the scale as 1 inch = 15 miles, 120 drops the half inch, and 9 is the number of half-inches without converting to miles.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 3 },
  { question: 'A water purifier produces 18 gallons in 40 minutes. At the same rate, how many gallons does it produce in 2 hours?', options: ['54', '6', '36', '720'], correctAnswer: 0, explanation: '2 hours is 120 minutes, which is $120 \\div 40 = 3$ times as long, so $18 \\times 3 = 54$ gallons. The answer 6 sets up the proportion upside down, 36 doubles 18 for the 2 hours without comparing 2 hours to 40 minutes, and 720 multiplies 18 by 40.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 3 },
  { question: 'Two trains are 360 miles apart and travel toward each other on parallel tracks, one at 70 mph and the other at 50 mph. In how many hours will they meet?', options: ['18', '3', '6', '7.2'], correctAnswer: 1, explanation: 'Moving toward each other, the gap shrinks by $70 + 50 = 120$ miles per hour, so they meet in $360 \\div 120 = 3$ hours. The answer 18 subtracts the speeds, 6 divides by the average speed of 60 mph as if only one train moved, and 7.2 lets only the slower train move.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 4 },
  { question: 'A tractor travels at 18 miles per hour. How many miles does it travel in 40 minutes?', options: ['720', '27', '12', '58'], correctAnswer: 2, explanation: '40 minutes is $\\frac{2}{3}$ hour, so $18 \\times \\frac{2}{3} = 6 \\times 2 = 12$ miles. The answer 720 multiplies by 40 without converting minutes to hours, 27 divides by $\\frac{2}{3}$ instead of multiplying, and 58 adds 18 and 40.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 4 },
  { question: 'One crew can unload a supply truck in 30 minutes. A second crew can unload it in 60 minutes. How long does the job take if both crews work together?', options: ['45 minutes', '20 minutes', '90 minutes', '30 minutes'], correctAnswer: 1, explanation: 'Rates: $\\frac{1}{30} + \\frac{1}{60} = \\frac{2}{60} + \\frac{1}{60} = \\frac{3}{60} = \\frac{1}{20}$ of the truck per minute, so 20 minutes. 45 minutes averages the times and 90 minutes adds them. 30 minutes is the faster crew alone, but with help the job must take less time.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 5 },

  // ── Hard (5) ──
  { question: 'A soldier drives 150 miles to a training site at 50 mph and drives home along the same road at 75 mph. What is the average speed for the round trip?', options: ['62.5 mph', '125 mph', '60 mph', '30 mph'], correctAnswer: 2, explanation: 'Going takes $150 \\div 50 = 3$ hours and coming home takes $150 \\div 75 = 2$ hours. Total: 300 miles in 5 hours, so $300 \\div 5 = 60$ mph. 62.5 mph averages the two speeds, 125 mph adds them, and 30 mph divides only the one-way 150 miles by the total time.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 6 },
  { question: 'A convoy truck averages 8 miles per gallon of diesel, and diesel costs \\$4.25 per gallon. What is the fuel cost for a 320-mile trip?', options: ['\\$34.00', '\\$40.00', '\\$1,360.00', '\\$170.00'], correctAnswer: 3, explanation: 'Gallons: $320 \\div 8 = 40$. Cost: $40 \\times 4.25 = 160 + 10 = 170$, so \\$170.00. \\$40.00 stops at the number of gallons, \\$34.00 multiplies the mpg by the price, and \\$1,360.00 multiplies the miles by the price and never uses the mpg.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 5 },
  { question: 'Ann can stock a supply shelf in 20 minutes, Ben in 30 minutes and Cy in 60 minutes. How long does the job take if all three work together?', options: ['10 minutes', '12 minutes', '20 minutes', '110 minutes'], correctAnswer: 0, explanation: 'Rates: $\\frac{1}{20} + \\frac{1}{30} + \\frac{1}{60} = \\frac{3}{60} + \\frac{2}{60} + \\frac{1}{60} = \\frac{6}{60} = \\frac{1}{10}$ of the shelf per minute, so 10 minutes. 12 minutes is Ann and Ben together, leaving out Cy; 20 minutes is Ann alone; and 110 minutes adds the three times.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 5 },
  { question: 'A cyclist leaves a trailhead at 9:00 a.m. riding 12 mph. At 9:30 a.m. a friend leaves the same trailhead on the same route riding 18 mph. How many minutes after the friend starts does she catch up to the cyclist?', options: ['12', '20', '60', '90'], correctAnswer: 2, explanation: 'Head start: in half an hour the cyclist rides $12 \\times \\frac{1}{2} = 6$ miles. The friend gains $18 - 12 = 6$ miles per hour, so she needs $6 \\div 6 = 1$ hour, or 60 minutes. The answer 90 counts from 9:00 instead of from when the friend starts, 20 divides the 6 miles by the friend\'s full 18 mph as if the cyclist had stopped, and 12 adds the speeds.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 4 },
  { question: 'A conveyor belt moves 240 boxes in 1 hour 20 minutes. At the same rate, how many boxes does it move in 3 hours?', options: ['600', '540', '720', '180'], correctAnswer: 1, explanation: '1 hour 20 minutes is 80 minutes, so the rate is $240 \\div 80 = 3$ boxes per minute. 3 hours is 180 minutes: $180 \\times 3 = 540$ boxes. The answer 600 treats 1 hour 20 minutes as 1.2 hours, 720 treats it as 1 hour, and 180 is the rate per hour (one step early).', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-ratios-rates', part: 3 },
  // ═══ Averages, Counting and Probability (asvab-ar-averages-probability) ═══
  // ---- Part 2: finding the average (mean), median ----
  { question: 'A barber gave 13, 18, 12, 20, 15 and 24 haircuts on six days. What was the average number of haircuts per day?', options: ['16', '17', '102', '12'], correctAnswer: 1, explanation: 'Sum: $13 + 18 + 12 + 20 + 15 + 24 = 102$, and $102 \\div 6 = 17$, which sits between 12 and 24. 102 is the total, not the average, 12 is the range ($24 - 12$), and 16 averages the two middle numbers of the list as printed (12 and 20) without putting it in order.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 2 },
  { question: 'Five crates of supplies weigh 96, 104, 99, 107 and 94 pounds. What is the average weight of a crate, in pounds?', options: ['125', '99', '13', '100'], correctAnswer: 3, explanation: 'Balance method around 100: $-4, +4, -1, +7, -6$ add to 0, so the average is exactly 100 (check: $500 \\div 5 = 100$). 125 divides the 500-pound total by 4 instead of 5, 99 is the median (the middle of 94, 96, 99, 104, 107), and 13 is the range ($107 - 94$).', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 2 },
  { question: 'The five employees of a small shop earn yearly salaries of \\$31,000, \\$34,000, \\$29,000, \\$36,000 and \\$120,000. What is the median salary?', options: ['\\$50,000', '\\$29,000', '\\$34,000', '\\$91,000'], correctAnswer: 2, explanation: 'Order first: \\$29,000, \\$31,000, \\$34,000, \\$36,000, \\$120,000. The middle value is \\$34,000. \\$50,000 is the mean ($250{,}000 \\div 5$), pulled up by the one high salary, \\$29,000 is the middle of the list as printed (the unordered trap), and \\$91,000 is the range.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 2 },
  { question: 'A family\'s electric bills for six months were \\$118, \\$124, \\$132, \\$109, \\$127 and \\$122. What was the average monthly bill?', options: ['\\$120', '\\$132', '\\$123', '\\$122'], correctAnswer: 3, explanation: 'Balance method around \\$120: $-2, +4, +12, -11, +7, +2$ add to $+12$, and $+12 \\div 6 = +2$, so the average is \\$122 (check: $732 \\div 6 = 122$). \\$132 adds the whole $+12$ to the guess without dividing, \\$120 is just the starting guess, and \\$123 is the median (the average of \\$122 and \\$124 in the ordered list).', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 2 },

  // ---- Part 3: missing values and weighted averages ----
  { question: 'A student scored 70, 80 and 90 on three quizzes. What score does he need on the fourth quiz to have an average of 85?', options: ['90', '100', '85', '340'], correctAnswer: 1, explanation: 'Target total: $85 \\times 4 = 340$. So far: $70 + 80 + 90 = 240$. Needed: $340 - 240 = 100$. 90 makes up only one quiz\'s 5-point shortfall instead of all three ($3 \\times 5 = 15$), 85 assumes he only has to match the target, and 340 is the target total.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 3 },
  { question: 'The 9 members of a work crew have an average age of 32. A 22-year-old joins the crew. What is the new average age?', options: ['27', '310', '31', '32'], correctAnswer: 2, explanation: 'Total before: $32 \\times 9 = 288$. Total after: $288 + 22 = 310$ years for 10 people, so $310 \\div 10 = 31$. 27 averages 32 and 22 as if there were only two people, 310 is the new total, and 32 assumes the average does not change, even though the new member is younger than the average.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 3 },
  { question: 'A company has 40 day-shift workers who average \\$18 an hour and 10 night-shift workers who average \\$23 an hour. What is the average hourly wage for all 50 workers?', options: ['\\$19.00', '\\$20.50', '\\$22.00', '\\$41.00'], correctAnswer: 0, explanation: 'Totals: $40 \\times 18 = 720$ and $10 \\times 23 = 230$, so $950 \\div 50 = 19$, or \\$19.00. \\$20.50 averages the two averages even though the day shift is four times as big, \\$22.00 attaches each wage to the wrong shift, and \\$41.00 adds the two averages.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 3 },
  { question: 'On a 10-question quiz, 5 recruits scored 6, 8 recruits scored 8 and 7 recruits scored 10. What was the average score of the 20 recruits?', options: ['8.0', '7.8', '54.7', '8.2'], correctAnswer: 3, explanation: 'Totals: $5 \\times 6 + 8 \\times 8 + 7 \\times 10 = 30 + 64 + 70 = 164$ points for 20 recruits, so $164 \\div 20 = 8.2$. 8.0 averages the scores 6, 8 and 10 without weighting by how many recruits got each, 7.8 attaches the counts to the scores in reverse order, and 54.7 divides 164 by 3 (the number of different scores) instead of by 20.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 3 },

  // ---- Part 4: counting outcomes ----
  { question: 'A bakery sells 5 kinds of bagels and 4 kinds of spreads. How many different bagel-and-spread orders (one of each) are possible?', options: ['20', '9', '40', '25'], correctAnswer: 0, explanation: 'Each bagel goes with each spread: $5 \\times 4 = 20$. 9 adds the choices instead of multiplying, 40 counts every order twice, and 25 multiplies the bagel choices by themselves ($5 \\times 5$) and leaves out the spreads.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 4 },
  { question: 'A storage locker uses a 3-digit code. Each digit is chosen from 1 through 9, and no digit may be repeated. How many different codes are possible?', options: ['729', '84', '504', '24'], correctAnswer: 2, explanation: 'Draw three blanks: 9 choices, then 8 left, then 7 left: $9 \\times 8 \\times 7 = 504$. 729 is $9 \\times 9 \\times 9$, which allows repeated digits, 84 ignores the order of the digits (but 123 and 321 are different codes), and 24 adds $9 + 8 + 7$.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 4 },
  { question: 'Seven finalists compete in a contest. Gold, silver and bronze medals go to three different finalists. In how many different ways can the medals be awarded?', options: ['210', '343', '35', '18'], correctAnswer: 0, explanation: '7 choices for gold, 6 left for silver, 5 left for bronze: $7 \\times 6 \\times 5 = 210$. 343 is $7 \\times 7 \\times 7$, which lets one finalist win more than one medal, 35 ignores which medal each person gets, and 18 adds $7 + 6 + 5$.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 4 },
  { question: 'A pizza shop has 6 toppings. A "double" pizza has 2 different toppings, and the customer also picks thin or thick crust. How many different double pizzas are possible?', options: ['60', '15', '72', '30'], correctAnswer: 3, explanation: 'Topping pairs (order does not matter): $\\frac{6 \\times 5}{2} = 15$. Times 2 crusts: $15 \\times 2 = 30$. 60 counts each topping pair twice, 15 forgets the crust choice, and 72 is $6 \\times 6 \\times 2$, which allows the same topping twice and counts pairs in both orders.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 4 },

  // ---- Part 5: basic probability ----
  { question: 'A charity raffle sold 200 tickets, and Maria bought 8 of them. One winning ticket is drawn. What is the probability that Maria wins?', options: ['$\\frac{1}{25}$', '$\\frac{1}{24}$', '$\\frac{1}{8}$', '$\\frac{1}{200}$'], correctAnswer: 0, explanation: 'Favorable over total: $\\frac{8}{200} = \\frac{1}{25}$. $\\frac{1}{24}$ divides her 8 tickets by the 192 tickets she did not buy instead of by all 200, $\\frac{1}{8}$ treats her tickets as the total, and $\\frac{1}{200}$ counts only one of her tickets.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 5 },
  { question: 'A parking lot holds 40 cars, and 12 of them are white. One car is chosen at random. What is the probability that it is not white?', options: ['$\\frac{3}{10}$', '$\\frac{7}{10}$', '$\\frac{3}{7}$', '$\\frac{7}{3}$'], correctAnswer: 1, explanation: 'Not white: $40 - 12 = 28$ cars, and $\\frac{28}{40} = \\frac{7}{10}$ (or $1 - \\frac{3}{10}$). $\\frac{3}{10}$ is the chance the car is white, $\\frac{3}{7}$ compares white cars to non-white cars, and $\\frac{7}{3}$ is bigger than 1, so it cannot be a probability.', difficulty: 'easy', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 5 },
  { question: 'A spinner has 5 equal sections, and 3 of them are green. The spinner is spun twice. What is the probability that it lands on green both times?', options: ['$\\frac{2}{5}$', '$\\frac{6}{5}$', '$\\frac{9}{25}$', '$\\frac{3}{5}$'], correctAnswer: 2, explanation: 'The spins are independent, so multiply: $\\frac{3}{5} \\times \\frac{3}{5} = \\frac{9}{25}$. $\\frac{6}{5}$ adds the probabilities and is bigger than 1, $\\frac{2}{5}$ is the chance of not landing on green on one spin, and $\\frac{3}{5}$ is the chance of green for one spin only.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 5 },
  { question: 'The names of 10 volunteers are put in a hat, and 2 of the volunteers work the night shift. Two names are drawn without replacement. What is the probability that both are night-shift volunteers?', options: ['$\\frac{1}{25}$', '$\\frac{14}{45}$', '$\\frac{1}{45}$', '$\\frac{1}{5}$'], correctAnswer: 2, explanation: 'First: $\\frac{2}{10}$. Then 1 night-shift name is left out of 9: $\\frac{1}{9}$. Multiply: $\\frac{2}{10} \\times \\frac{1}{9} = \\frac{2}{90} = \\frac{1}{45}$. $\\frac{1}{25}$ uses $\\frac{2}{10}$ twice, as if the first name went back, $\\frac{14}{45}$ adds the two fractions, and $\\frac{1}{5}$ is only the first draw.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 5 },
  { question: 'A standard six-sided die is rolled twice. What is the probability that neither roll is a 6?', options: ['$\\frac{1}{3}$', '$\\frac{2}{3}$', '$\\frac{5}{6}$', '$\\frac{25}{36}$'], correctAnswer: 3, explanation: 'Each roll is not a 6 with probability $\\frac{5}{6}$, and the rolls are independent: $\\frac{5}{6} \\times \\frac{5}{6} = \\frac{25}{36}$. $\\frac{1}{3}$ adds $\\frac{1}{6} + \\frac{1}{6}$, a rough (and wrong) chance of rolling at least one 6, which is the opposite of what is asked; $\\frac{2}{3}$ subtracts $\\frac{1}{6}$ twice from 1 instead of multiplying, and $\\frac{5}{6}$ covers only one roll.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 5 },

  // ---- Part 6: traps ----
  { question: 'A 2-digit code is made by choosing each digit from 1, 2 and 3, and digits may repeat. If one such code is picked at random, what is the probability that both digits are the same?', options: ['$\\frac{1}{9}$', '$\\frac{2}{3}$', '$\\frac{1}{3}$', '$\\frac{1}{2}$'], correctAnswer: 2, explanation: 'There are $3 \\times 3 = 9$ codes, and 3 of them (11, 22, 33) have matching digits: $\\frac{3}{9} = \\frac{1}{3}$. $\\frac{1}{2}$ comes from listing unordered pairs (11, 22, 33, 12, 13, 23), but 12 and 21 are different codes; $\\frac{1}{9}$ counts only one matching code, and $\\frac{2}{3}$ is the chance the digits differ.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 6 },
  { question: 'A store is closed on Sundays and sells nothing that day. From Monday through Saturday it sold 40, 38, 50, 44, 36 and 44 boxes of paper. What was the average number of boxes sold per day for the full 7-day week?', options: ['42', '36', '252', '44'], correctAnswer: 1, explanation: 'Sum: $40 + 38 + 50 + 44 + 36 + 44 = 252$. The question asks about all 7 days, so $252 \\div 7 = 36$. 42 divides by 6 (the wrong count for a 7-day week), 252 is the total, and 44 is the mode.', difficulty: 'medium', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 6 },
  { question: 'A warehouse has 30 workers who average 84 packages per hour. The 12 workers on the morning crew average 78 packages per hour. What is the average for the other 18 workers?', options: ['88', '90', '81', '1,584'], correctAnswer: 0, explanation: 'All 30: $30 \\times 84 = 2{,}520$. Morning crew: $12 \\times 78 = 936$. Others: $2{,}520 - 936 = 1{,}584$, and $1{,}584 \\div 18 = 88$. 90 assumes the two crews balance evenly around 84 (6 below, so 6 above), which is only true for equal-sized groups; 81 averages 78 and 84, and 1,584 is the other crew\'s total.', difficulty: 'hard', domain: 'arithmetic-reasoning', topicSlug: 'asvab-ar-averages-probability', part: 6 },
]
